CREATE OR REPLACE FUNCTION public.current_user_org_id() RETURNS uuid AS $$ SELECT organization_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; $$ LANGUAGE sql SECURITY DEFINER STABLE;
CREATE OR REPLACE FUNCTION public.current_user_role() RETURNS user_role AS $$ SELECT role FROM public.profiles WHERE user_id = auth.uid() LIMIT 1; $$ LANGUAGE sql SECURITY DEFINER STABLE;
CREATE OR REPLACE FUNCTION public.current_user_employee_id() RETURNS uuid AS $$ SELECT id FROM public.employees WHERE user_id = auth.uid() LIMIT 1; $$ LANGUAGE sql SECURITY DEFINER STABLE;
CREATE OR REPLACE FUNCTION public.is_hr_or_above() RETURNS boolean AS $$ SELECT current_user_role() IN ('super_admin','org_admin','hr_officer'); $$ LANGUAGE sql SECURITY DEFINER STABLE;
DROP POLICY IF EXISTS "org_sel" ON organizations; CREATE POLICY "org_sel" ON organizations FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR id=current_user_org_id());
DROP POLICY IF EXISTS "org_mng" ON organizations; CREATE POLICY "org_mng" ON organizations FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (id=current_user_org_id() AND current_user_role()='org_admin')) WITH CHECK (current_user_role()='super_admin' OR (id=current_user_org_id() AND current_user_role()='org_admin'));
DROP POLICY IF EXISTS "roles_sel" ON roles; CREATE POLICY "roles_sel" ON roles FOR SELECT TO authenticated USING (true);
DROP POLICY IF EXISTS "prof_sel" ON profiles; CREATE POLICY "prof_sel" ON profiles FOR SELECT TO authenticated USING (user_id=auth.uid() OR current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "prof_ins" ON profiles; CREATE POLICY "prof_ins" ON profiles FOR INSERT TO authenticated WITH CHECK (user_id=auth.uid() OR (organization_id=current_user_org_id() AND is_hr_or_above()) OR current_user_role()='super_admin');
DROP POLICY IF EXISTS "prof_upd" ON profiles; CREATE POLICY "prof_upd" ON profiles FOR UPDATE TO authenticated USING (user_id=auth.uid() OR current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (user_id=auth.uid() OR current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "dept_sel" ON departments; CREATE POLICY "dept_sel" ON departments FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR organization_id=current_user_org_id());
DROP POLICY IF EXISTS "dept_mng" ON departments; CREATE POLICY "dept_mng" ON departments FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "emp_sel" ON employees; CREATE POLICY "emp_sel" ON employees FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR organization_id=current_user_org_id());
DROP POLICY IF EXISTS "emp_mng" ON employees; CREATE POLICY "emp_mng" ON employees FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "consent_mng" ON consent_records; CREATE POLICY "consent_mng" ON consent_records FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "face_admin" ON face_profiles; CREATE POLICY "face_admin" ON face_profiles FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "att_sel" ON attendance_sessions; CREATE POLICY "att_sel" ON attendance_sessions FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()) OR employee_id=current_user_employee_id());
DROP POLICY IF EXISTS "att_mng" ON attendance_sessions; CREATE POLICY "att_mng" ON attendance_sessions FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "log_sel" ON attendance_logs; CREATE POLICY "log_sel" ON attendance_logs FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()) OR employee_id=current_user_employee_id());
DROP POLICY IF EXISTS "log_mng" ON attendance_logs; CREATE POLICY "log_mng" ON attendance_logs FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above())) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "audit_sel" ON audit_logs; CREATE POLICY "audit_sel" ON audit_logs FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND is_hr_or_above()));
DROP POLICY IF EXISTS "set_sel" ON app_settings; CREATE POLICY "set_sel" ON app_settings FOR SELECT TO authenticated USING (current_user_role()='super_admin' OR organization_id=current_user_org_id());
DROP POLICY IF EXISTS "set_mng" ON app_settings; CREATE POLICY "set_mng" ON app_settings FOR ALL TO authenticated USING (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND current_user_role()='org_admin')) WITH CHECK (current_user_role()='super_admin' OR (organization_id=current_user_org_id() AND current_user_role()='org_admin'));
